      { only = "Shaman", when = { { "onquest", quests = { 94374 } }, { "has", item = 6635, n = 1, neg = true } },
        { "text", text = "Lost the Earth Sapta?" },
        { "text", text = "Only if the Earth Sapta is gone from your bags (drunk away from the stone, or sold): Teo gives you another." },
        { "goto", x = 28.79, y = 66.18, zone = "1426" },
