        { "goto", x = 24.8, y = 61.8, zone = "1426" },
        { "accept", quest = 94375, text = "Accept Call of Earth (it hands you the |cOXP_LOOT_Rough Quartz|r: keep it)" },
        { "target", name = "Minor Manifestation of Earth" },
      },
      { only = "Shaman",
        { "text", text = "|cOXP_FRIENDLY_Teo Hammerstorm|r" },
