        { "goto", x = 27.25, y = 8.3, zone = "1455" },
        { "turnin", quest = 1880, text = "Turn in Mage-tastic Gizmonitor (|cOXP_FRIENDLY_Bink|r: |cOXP_LOOT_Arcane Orb|r or |cOXP_LOOT_Arcane Staff|r)" },
        { "target", name = "Bink" },
      },
      { only = "Human Mage/Gnome Mage",
        { "text", text = "|cOXP_FRIENDLY_Belann Windwood|r's wand (optional)" },
        { "text", text = "|cOXP_FRIENDLY_Belann Windwood|r's quest is open to Human and Gnome mages too, if you ever visit Valanaar on Zephras Isle, the Skyborne home: |cOXP_FRIENDLY_Anathamaas Aetherwind|r, the town's mage trainer, sends you to |cOXP_FRIENDLY_Belann Windwood|r next door, who wants a |cOXP_LOOT_Wind-Infused Bough|r from the ground by the Windstone Formations south of Falaath Village, for the |cOXP_LOOT_Windbough Wand|r. It does not shut out the staff or the orb." },
        { "goto", x = 65.91, y = 80.57, zone = "2521" },
        { "accept", optional = true, quest = 93791, text = "Accept Speak with Belann" },
        { "target", name = "Anathamaas Aetherwind" },
