      { only = "Priest", when = { { "zone", name = "Dun Morogh" }, { "onquest", neg = true, quests = { 94817, 94821, 94822, 94823, 94824, 94825, 94826 } } },
        { "text", text = "Class quest: {quest:94817} and {quest:94818}" },
        { "text", text = "Confounding Flash: |cOXP_FRIENDLY_Maxan Anvol|r" },
        { "text", text = "At 10, |cOXP_FRIENDLY_Maxan Anvol|r, the priest trainer inside the Thunderbrew Distillery in Kharanos, hands you a Confounding Flash letter for |cOXP_FRIENDLY_High Priestess Mims|r in Ironforge. Kharanos is on the road up to the city." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 47.34, y = 52.19, zone = "1426" },
        { "text", text = "Use Maxan Anvol (|cOXP_FRIENDLY_Maxan Anvol|r: take his Confounding Flash letter)" },
      },
      { only = "Priest", when = { { "zone", name = "Elwynn Forest" }, { "onquest", neg = true, quests = { 94817, 94821, 94822, 94823, 94824, 94825, 94826 } } },
        { "text", text = "Confounding Flash: |cOXP_FRIENDLY_Priestess Josetta|r" },
        { "text", text = "At 10 in Elwynn Forest, |cOXP_FRIENDLY_Priestess Josetta|r, upstairs in the Lion's Pride Inn in Goldshire, hands you a Confounding Flash letter for |cOXP_FRIENDLY_High Priestess Mims|r in Ironforge." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 43.28, y = 65.72, zone = "1429" },
