        { "goto", x = 43.28, y = 65.72, zone = "1429" },
        { "text", text = "Use Priestess Josetta (|cOXP_FRIENDLY_Priestess Josetta|r: take Returning Home)" },
      },
      { only = "Priest", when = { { "zone", name = "Dun Morogh" }, { "onquest", neg = true, quests = { 5627, 5628, 5629, 5630, 5631, 5632, 5633 } } },
        { "text", text = "Starshards: |cOXP_FRIENDLY_Maxan Anvol|r" },
        { "text", text = "At 10 in Dun Morogh, |cOXP_FRIENDLY_Maxan Anvol|r, the priest trainer inside the Thunderbrew Distillery in Kharanos, hands you Returning Home, a letter for |cOXP_FRIENDLY_Priestess Alathea|r in Darnassus." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 47.34, y = 52.19, zone = "1426" },
