      { only = "Priest", when = { { "zone", name = "Stormwind City" }, { "onquest", neg = true, quests = { 5672, 5673, 5674, 5675 } } },
        { "text", text = "Elune's Grace: |cOXP_FRIENDLY_High Priestess Laurena|r" },
        { "text", text = "At 20 in Stormwind, |cOXP_FRIENDLY_High Priestess Laurena|r at the altar of the Cathedral of Light hands you an Elune's Grace letter for |cOXP_FRIENDLY_Priestess Alathea|r in Darnassus. |cOXP_FRIENDLY_Nara Meideros|r in the Park has the same letter." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 49.53, y = 44.6, zone = "1453" },
