        { "target", name = "Priestess Alathea" },
      },
      { only = "Priest", when = { { "onquest", neg = true, quests = { 5676, 5677, 5678 } } },
        { "text", text = "Feedback: |cOXP_FRIENDLY_High Priestess Laurena|r" },
        { "text", text = "At 20, |cOXP_FRIENDLY_High Priestess Laurena|r at the altar of the Cathedral of Light teaches Feedback with a quest she gives and takes back at once." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 49.53, y = 44.6, zone = "1453" },
        { "accept", quest = 5676, text = "Accept Arcane Feedback" },
