        { "target", name = "High Priestess Laurena" },
      },
      { only = "Priest", when = { { "zone", name = "Darnassus" }, { "onquest", neg = true, quests = { 5641, 5645, 5647 } } },
        { "text", text = "Chastise: |cOXP_FRIENDLY_Priestess Alathea|r" },
        { "text", text = "At 20 in Darnassus, |cOXP_FRIENDLY_Priestess Alathea|r, on the upper balcony of the Temple of the Moon beside |cOXP_FRIENDLY_Tyrande Whisperwind|r, hands you a Chastise letter for |cOXP_FRIENDLY_High Priest Rohan|r in Ironforge." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "text", text = "Use Priestess Alathea (|cOXP_FRIENDLY_Priestess Alathea|r: take her Chastise letter)" },
      },
      { only = "Priest", when = { { "onquest", neg = true, quests = { 5641, 5645, 5647 } } },
        { "text", text = "Chastise: |cOXP_FRIENDLY_High Priest Rohan|r" },
        { "text", text = "At 20, |cOXP_FRIENDLY_High Priest Rohan|r in the |cOXP_PICK_Hall of Mysteries|r teaches Chastise with a quest he gives and takes back at once. Forever renamed it from A Lack of Fear: Chastise damages a humanoid and roots it for 2 seconds (instant, 2-minute cooldown), and every priest now trains Fear Ward." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 24.73, y = 8.16, zone = "1455" },
        { "accept", quest = 5641, text = "Accept Chastise" },
        { "target", name = "High Priest Rohan" },
        { "goto", x = 24.73, y = 8.16, zone = "1455" },
        { "turnin", quest = 5641, text = "Turn in Chastise (|cOXP_FRIENDLY_High Priest Rohan|r: Chastise)" },
