        { "text", text = "Contingency Plan: Laurena's letter" },
        { "text", text = "Hand Laurena's letter to |cOXP_FRIENDLY_High Priestess Mims|r in the |cOXP_PICK_Hall of Mysteries|r, Ironforge's |cOXP_PICK_Mystic Ward|r: the Deeprun Tram from Stormwind's |cOXP_PICK_Dwarven District|r." },
        { "goto", x = 24.59, y = 10, zone = "1455" },
        { "turnin", quest = 94819, text = "Turn in Contingency Plan (|cOXP_FRIENDLY_High Priestess Mims|r: Contingency Plan)" },
