        { "accept", only = "Warlock", quest = 1715, text = "Accept The Slaughtered Lamb (|cOXP_FRIENDLY_Lago Blackwrench|r: |cOXP_FRIENDLY_Gakin the Darkbinder|r in Stormwind takes it)" },
        { "target", name = "Lago Blackwrench", only = "Warlock" },
        { "train", only = "Rogue/Shaman/Warlock", text = "Train your new spells" },
      },
      { only = "Paladin",
        { "text", text = "The Tome of Divinity" },
        { "text", text = "West from the |cOXP_PICK_Forlorn Cavern|r into the |cOXP_PICK_Mystic Ward|r: |cOXP_FRIENDLY_Brandur Ironhammer|r, |cOXP_FRIENDLY_Tiza Battleforge|r and |cOXP_FRIENDLY_Muiredon Battleforge|r are in the |cOXP_PICK_Hall of Mysteries|r, |cOXP_FRIENDLY_Tiza Battleforge|r and |cOXP_FRIENDLY_Muiredon Battleforge|r on its upper floor: the stairs up start just north-east of |cOXP_FRIENDLY_Brandur Ironhammer|r. |cOXP_FRIENDLY_John Turner|r, a beggar, wanders the city. He asks for ten |cOXP_LOOT_Linen Cloth|r: the troggs and trolls of Dun Morogh drop it, and the Auction House sells it." },
