        { "goto", x = 23.13, y = 6.14, zone = "1455" },
        { "accept", optional = true, quest = 2999, text = "Accept Tome of Divinity (|cOXP_FRIENDLY_Brandur Ironhammer|r, Ironforge)" },
        { "target", name = "Brandur Ironhammer" },
