        { "turnin", quest = 1338, text = "Turn in Stormpike's Order" },
        { "target", name = "Furen Longbeard" },
      },
      {
        { "text", text = "|cOXP_FRIENDLY_Baros Alexston|r" },
        { "text", text = "From the |cOXP_PICK_Dwarven District|r south-west to |cOXP_PICK_Cathedral Square|r: |cOXP_FRIENDLY_Baros Alexston|r's compass is in his old house in Westfall, on the way. The flight master and the |cOXP_PICK_Trade District|r are south of the square." },
        { "goto", x = 57.74, y = 47.86, zone = "1453" },
        { "accept", quest = 399, text = "Accept Humble Beginnings" },
        { "target", name = "Baros Alexston" },
