        { "target", name = "Quel'ana Quickgale" },
      },
      { only = "Skyborne Hunter",
        { "text", text = "|cOXP_ENEMY_Windsong Crawler|r" },
        { "text", text = "Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of Valanaar, among the crabs. How the rod works: target a living crawler, use the |cOXP_LOOT_Taming Rod|r and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges. Killing one does not count. Keep each rod: it goes back to |cOXP_FRIENDLY_Quel'ana Quickgale|r." },
        { "goto", x = 53.8, y = 77, zone = "2521" },
        { "complete", obj = 1, quest = 94978, text = "Kill Windsong Crawler: 1 (Use the |cOXP_LOOT_Taming Rod|r on a living crawler)" },
        { "mob", name = "Windsong Crawler" },
        { "goto", x = 59.56, y = 72.63, zone = "2521" },
        { "turnin", quest = 94978, text = "Turn in Taming the Beast" },
        { "target", name = "Quel'ana Quickgale" },
        { "goto", x = 59.56, y = 72.63, zone = "2521" },
        { "accept", quest = 94979, text = "Accept Taming the Beast" },
        { "target", name = "Quel'ana Quickgale" },
      },
      { only = "Skyborne Hunter",
        { "text", text = "|cOXP_ENEMY_Ornery Galestrider|r" },
        { "text", text = "Dismiss the crawler first (right-click the pet portrait, Dismiss Pet). Ornery Galestriders graze in the Gustberry Lowlands, the fields a short walk west and south-west of Valanaar." },
        { "goto", x = 59.17, y = 74, zone = "2521" },
        { "complete", obj = 1, quest = 94979, text = "Kill Ornery Galestrider: 1 (Use the |cOXP_LOOT_Taming Rod|r on a living galestrider)" },
