        { "target", name = "Quel'ana Quickgale" },
      },
      { only = "Skyborne Hunter",
        { "text", text = "|cOXP_ENEMY_Vuldren Alpha|r" },
        { "text", text = "Dismiss the galestrider. Vuldren Alphas hunt in the same Gustberry Lowlands, a little further south." },
        { "goto", x = 59.69, y = 72.66, zone = "2521" },
        { "complete", obj = 1, quest = 94013, text = "Kill Vuldren Alpha: 1 (Use the |cOXP_LOOT_Taming Rod|r on a living alpha)" },
