        { "goto", x = 45.81, y = 53.04, zone = "1426" },
        { "turnin", quest = 6085, text = "Turn in Taming the Beast (|cOXP_FRIENDLY_Grif Wildheart|r: Tame Beast)" },
        { "target", name = "Grif Wildheart" },
        { "goto", x = 45.81, y = 53.04, zone = "1426" },
        { "accept", quest = 6086, text = "Accept Training the Beast" },
        { "target", name = "Grif Wildheart" },
