      { only = "NightElf Hunter", when = { { "onquest", neg = true, quests = { 94792, 94863, 94864, 94793 } }, { "turnedin", neg = true, quest = 94792 } },
        { "text", text = "|cOXP_ENEMY_Nightsaber Stalker|r" },
        { "text", text = "Dismiss the spider first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of Lake Al'Ameth, south of Dolanaar; the plain Nightsabers by the village do not count." },
        { "goto", x = 55.79, y = 72.27, zone = "1438" },
        { "complete", obj = 1, quest = 6101, text = "Kill Nightsaber Stalker: 1 (Use the |cOXP_LOOT_Taming Rod|r on a living stalker)" },
