      { only = "NightElf Hunter", when = { { "onquest", neg = true, quests = { 94792, 94863, 94864, 94793 } }, { "turnedin", neg = true, quest = 94792 } },
        { "text", text = "|cOXP_ENEMY_Strigid Screecher|r" },
        { "text", text = "Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of Dolanaar." },
        { "goto", x = 64.2, y = 67.23, zone = "1438" },
        { "complete", obj = 1, quest = 6102, text = "Kill Strigid Screecher: 1 (Use the |cOXP_LOOT_Taming Rod|r on a living owl)" },
