      { only = "Dwarf Hunter", when = { { "onquest", neg = true, quests = { 94792, 94863, 94864, 94793 } }, { "turnedin", neg = true, quest = 94792 } },
        { "text", text = "|cOXP_FRIENDLY_Belia Thundergranite|r in Ironforge" },
        { "text", text = "|cOXP_FRIENDLY_Belia Thundergranite|r, the pet trainer, stands in the |cOXP_PICK_Hall of Arms|r in Ironforge's |cOXP_PICK_Military Ward|r, by the hunter trainers." },
