        { "text", text = "At 20 in Ironforge, |cOXP_FRIENDLY_High Priest Rohan|r in the |cOXP_PICK_Hall of Mysteries|r (|cOXP_PICK_Mystic Ward|r) hands you an Elune's Grace letter for |cOXP_FRIENDLY_Priestess Alathea|r in Darnassus." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 24.73, y = 8.16, zone = "1455" },
        { "text", text = "Use High Priest Rohan (|cOXP_FRIENDLY_High Priest Rohan|r: take his Elune's Grace letter)" },
      },
      { only = "Priest", when = { { "onquest", neg = true, quests = { 5672, 5673, 5674, 5675 } } },
        { "text", text = "Elune's Grace: |cOXP_FRIENDLY_Priestess Alathea|r" },
        { "text", text = "At 20, |cOXP_FRIENDLY_Priestess Alathea|r on the upper balcony of the Temple of the Moon, beside |cOXP_FRIENDLY_Tyrande Whisperwind|r, teaches Elune's Grace with a quest she gives and takes back at once. In Forever, Elune's Grace halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "accept", quest = 5672, text = "Accept Elune's Grace" },
        { "target", name = "Priestess Alathea" },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "turnin", quest = 5672, text = "Turn in Elune's Grace (|cOXP_FRIENDLY_Priestess Alathea|r: Elune's Grace)" },
        { "target", name = "Priestess Alathea" },
      },
      { only = "Priest", when = { { "onquest", quests = { 5673 } } },
        { "text", text = "Elune's Grace: Laurena's letter" },
        { "text", text = "Hand Laurena's letter to |cOXP_FRIENDLY_Priestess Alathea|r, on the upper balcony of the Temple of the Moon in Darnassus, beside |cOXP_FRIENDLY_Tyrande Whisperwind|r: the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus." },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "turnin", quest = 5673, text = "Turn in Elune's Grace (|cOXP_FRIENDLY_Priestess Alathea|r: Elune's Grace)" },
        { "target", name = "Priestess Alathea" },
      },
      { only = "Priest", when = { { "onquest", quests = { 5674 } } },
        { "text", text = "Elune's Grace: Nara's letter" },
        { "text", text = "Hand Nara's letter to |cOXP_FRIENDLY_Priestess Alathea|r, on the upper balcony of the Temple of the Moon in Darnassus, beside |cOXP_FRIENDLY_Tyrande Whisperwind|r: the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus." },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "turnin", quest = 5674, text = "Turn in Elune's Grace (|cOXP_FRIENDLY_Priestess Alathea|r: Elune's Grace)" },
        { "target", name = "Priestess Alathea" },
      },
      { only = "Human Rogue/Skyborne Rogue",
        { "text", text = "Class quest: {item:7298} (Alliance)" },
        { "text", text = "Seek out SI: 7" },
        { "text", text = "At 10 |cOXP_FRIENDLY_Keryn Sylvius|r, the rogue trainer upstairs in the Lion's Pride Inn in Goldshire, gives you a package for |cOXP_FRIENDLY_Master Mathias Shaw|r in Stormwind. Train Pick Pocket if you lack it: this chain needs it." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 43.87, y = 65.94, zone = "1429" },
        { "accept", quest = 2205, text = "Accept Seek out SI: 7" },
        { "target", name = "Keryn Sylvius" },
      },
      { only = "Human Rogue/Skyborne Rogue",
        { "text", text = "|cOXP_FRIENDLY_Master Mathias Shaw|r" },
        { "text", text = "Head north to Stormwind. Shaw stands upstairs in the SI:7 building in |cOXP_PICK_Old Town|r (the quest says the Barracks; it means SI:7)." },
        { "goto", x = 78.31, y = 70.74, zone = "1453" },
        { "turnin", quest = 2205, text = "Turn in Seek out SI: 7" },
        { "target", name = "Master Mathias Shaw" },
        { "goto", x = 78.31, y = 70.74, zone = "1453" },
        { "accept", quest = 2206, text = "Accept Snatch and Grab" },
        { "target", name = "Master Mathias Shaw" },
      },
      { only = "Human Rogue/Skyborne Rogue",
        { "text", text = "|cOXP_ENEMY_Defias Dockmaster|r" },
        { "text", text = "The |cOXP_ENEMY_Defias Dockmaster|r (level 10, a goblin) works in the dock house at Jerod's Landing, on the river at Elwynn's southern edge, south of Goldshire. Stealth in and Pick Pocket him from behind: the schedule never drops from his corpse. Do not open with Sap or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death." },
        { "goto", x = 48.06, y = 86.96, zone = "1429" },
        { "complete", obj = 1, quest = 2206, text = "Defias Shipping Schedule: 1" },
        { "mob", name = "Defias Dockmaster" },
      },
      { only = "Human Rogue/Skyborne Rogue",
        { "text", text = "Back to Mathias Shaw" },
        { "goto", x = 78.31, y = 70.74, zone = "1453" },
        { "turnin", quest = 2206, text = "Turn in Snatch and Grab (|cOXP_FRIENDLY_Master Mathias Shaw|r, SI:7)" },
        { "target", name = "Master Mathias Shaw" },
      },
      { only = "Dwarf Rogue/Gnome Rogue",
        { "text", text = "Road to Salvation" },
        { "text", text = "At 10 |cOXP_FRIENDLY_Hogral Bakkan|r, the rogue trainer in the Thunderbrew Distillery in Kharanos, sends you to |cOXP_FRIENDLY_Hulfdan Blackbeard|r in Ironforge." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 47.56, y = 52.61, zone = "1426" },
        { "accept", quest = 2218, text = "Accept Road to Salvation" },
        { "target", name = "Hogral Bakkan" },
      },
      { only = "Dwarf Rogue/Gnome Rogue",
        { "text", text = "|cOXP_FRIENDLY_Hulfdan Blackbeard|r" },
        { "text", text = "|cOXP_FRIENDLY_Hulfdan Blackbeard|r is in the |cOXP_PICK_Forlorn Cavern|r, the rogue quarter in the north of Ironforge: go into the building with a shady dealer outside and down the stairs." },
        { "goto", x = 51.96, y = 14.84, zone = "1455" },
        { "turnin", quest = 2218, text = "Turn in Road to Salvation" },
        { "target", name = "Hulfdan Blackbeard" },
        { "goto", x = 51.96, y = 14.84, zone = "1455" },
        { "accept", quest = 2238, text = "Accept Simple Subterfugin'" },
        { "target", name = "Hulfdan Blackbeard" },
      },
      { only = "Dwarf Rogue/Gnome Rogue",
        { "text", text = "|cOXP_FRIENDLY_Onin MacHammar|r" },
        { "text", text = "Head west to Gnomeregan. Beside the road to its entrance stands a wooden spiral tower: |cOXP_FRIENDLY_Onin MacHammar|r waits stealthed on the top platform, next to a level 10 |cOXP_ENEMY_Leper Gnome|r, so you only see him up close." },
        { "goto", x = 25.16, y = 44.45, zone = "1426" },
        { "turnin", quest = 2238, text = "Turn in Simple Subterfugin'" },
        { "target", name = "Onin MacHammar" },
        { "goto", x = 25.16, y = 44.45, zone = "1426" },
        { "accept", quest = 2239, text = "Accept Onin's Report" },
        { "target", name = "Onin MacHammar" },
      },
      { only = "Dwarf Rogue/Gnome Rogue",
        { "text", text = "Back to |cOXP_FRIENDLY_Hulfdan Blackbeard|r" },
        { "goto", x = 51.96, y = 14.84, zone = "1455" },
        { "turnin", quest = 2239, text = "Turn in Onin's Report (|cOXP_FRIENDLY_Hulfdan Blackbeard|r, Ironforge)" },
        { "target", name = "Hulfdan Blackbeard" },
      },
      { only = "NightElf Rogue",
        { "text", text = "The Apple Falls" },
        { "text", text = "At 10 |cOXP_FRIENDLY_Jannok Breezesong|r, the rogue trainer in the Dolanaar inn, gives you a rose for |cOXP_FRIENDLY_Syurna|r in Darnassus. If you lose the rose, abandon the quest and take it again." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 56.38, y = 60.14, zone = "1438" },
        { "accept", quest = 2241, text = "Accept The Apple Falls" },
        { "target", name = "Jannok Breezesong" },
      },
      { only = "NightElf Rogue",
        { "text", text = "|cOXP_FRIENDLY_Syurna|r" },
        { "text", text = "Head west to Darnassus. |cOXP_FRIENDLY_Syurna|r is below ground in the Cenarion Enclave: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground." },
        { "goto", x = 36.99, y = 21.91, zone = "1457" },
        { "turnin", quest = 2241, text = "Turn in The Apple Falls" },
        { "target", name = "Syurna" },
        { "goto", x = 36.99, y = 21.91, zone = "1457" },
        { "accept", quest = 2242, text = "Accept Destiny Calls" },
        { "target", name = "Syurna" },
      },
      { only = "NightElf Rogue",
        { "text", text = "|cOXP_ENEMY_Sethir the Ancient|r" },
        { "text", text = "|cOXP_ENEMY_Sethir the Ancient|r (level 12 satyr) lives out on a great branch north of the Oracle Glade: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then Sprint away. He is back 8 1/2 minutes after a death." },
        { "goto", x = 37.11, y = 22.83, zone = "1438" },
        { "complete", obj = 1, quest = 2242, text = "Sethir's Journal: 1" },
        { "mob", name = "Sethir the Ancient" },
      },
      { only = "Shaman",
        { "text", text = "Class quest: {quest:94449} (Alliance)" },
        { "text", text = "Call of Fire" },
        { "text", text = "At 10 |cOXP_FRIENDLY_Ingrid Dunwald|r, the shaman trainer in Kharanos, or |cOXP_FRIENDLY_Eldrun Stormbreaker|r, the shaman trainer in Ironforge, sends you to |cOXP_FRIENDLY_Bruegs Kindleborn|r." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 47.58, y = 51.95, zone = "1426" },
        { "accept", quest = 94449, text = "Accept Call of Fire (|cOXP_FRIENDLY_Ingrid Dunwald|r, Kharanos; or |cOXP_FRIENDLY_Eldrun Stormbreaker|r, Ironforge)" },
        { "target", name = "Ingrid Dunwald" },
      },
      { only = "Shaman",
        { "text", text = "|cOXP_FRIENDLY_Bruegs Kindleborn|r" },
        { "text", text = "Follow the road east to the tunnel towards South Gate Outpost. Out of the first tunnel, keep left past |cOXP_FRIENDLY_Mountaineer Barleybrew|r and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to |cOXP_FRIENDLY_Bruegs Kindleborn|r' cave above the farm. He hands you the |cOXP_LOOT_Torch of the Dormant Flame|r: keep it until the end of the chain." },
        { "goto", x = 87.94, y = 44.8, zone = "1426" },
        { "turnin", quest = 94449, text = "Turn in Call of Fire" },
        { "target", name = "Bruegs Kindleborn" },
        { "goto", x = 87.94, y = 44.8, zone = "1426" },
        { "accept", quest = 94465, text = "Accept Call of Fire" },
        { "target", name = "Bruegs Kindleborn" },
      },
      { only = "Shaman",
        { "text", text = "|cOXP_FRIENDLY_Braldir Ashmantle|r" },
        { "text", text = "From |cOXP_FRIENDLY_Bruegs Kindleborn|r' ledge you can drop carefully down the mountain into Loch Modan, or walk back through the tunnel. |cOXP_FRIENDLY_Braldir Ashmantle|r keeps the shrine on the peak just south of Thelsamar: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak." },
        { "goto", x = 32.17, y = 65.97, zone = "1432" },
        { "turnin", quest = 94465, text = "Turn in Call of Fire" },
        { "target", name = "Braldir Ashmantle" },
        { "goto", x = 32.17, y = 65.97, zone = "1432" },
        { "accept", quest = 94466, text = "Accept Call of Fire" },
        { "target", name = "Braldir Ashmantle" },
      },
      { only = "Shaman",
        { "text", text = "|cOXP_LOOT_Reagent Pouch|r" },
        { "text", text = "The Stonesplinter Seers (level 13-14) stand among the troggs of Stonesplinter Valley in the south of the loch, and in the trogg camps north-east of Thelsamar. They throw Lightning Bolts from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes." },
        { "goto", x = 36.75, y = 77.75, zone = "1432" },
        { "complete", obj = 2, quest = 94466, text = "Reagent Pouch: 1" },
        { "mob", name = "Stonesplinter Seer" },
      },
      { only = "Shaman",
        { "text", text = "|cOXP_LOOT_Fire Tar|r" },
        { "text", text = "The Tunnel Rat Geomancers (level 12-13) work only inside the Silver Stream Mine at the north end of the loch, past Thelsamar. They cast Fire Blast behind a Fire Shield and run for help at low health." },
        { "goto", x = 35.55, y = 27.92, zone = "1432" },
        { "complete", obj = 1, quest = 94466, text = "Fire Tar: 1" },
        { "mob", name = "Tunnel Rat Geomancer" },
      },
      { only = "Shaman",
        { "text", text = "|cOXP_FRIENDLY_Braldir Ashmantle|r" },
        { "text", text = "Back up the trail to |cOXP_FRIENDLY_Braldir Ashmantle|r. He makes the |cOXP_LOOT_Fire Sapta|r from the tar and the pouch: keep it with the torch." },
        { "goto", x = 32.17, y = 65.97, zone = "1432" },
        { "turnin", quest = 94466, text = "Turn in Call of Fire" },
        { "target", name = "Braldir Ashmantle" },
        { "goto", x = 32.17, y = 65.97, zone = "1432" },
        { "accept", quest = 94467, text = "Accept Call of Fire" },
        { "target", name = "Braldir Ashmantle" },
      },
      { only = "Shaman", when = { { "onquest", quests = { 94467 } }, { "has", item = 6636, n = 1, neg = true } },
        { "text", text = "Lost the Fire Sapta?" },
        { "text", text = "Only if the Fire Sapta is gone from your bags: |cOXP_FRIENDLY_Braldir Ashmantle|r gives you another." },
        { "goto", x = 32.17, y = 65.97, zone = "1432" },
        { "turnin", quest = 94473, text = "Turn in Fire Sapta (|cOXP_FRIENDLY_Braldir Ashmantle|r: a new Fire Sapta)" },
        { "target", name = "Braldir Ashmantle" },
      },
      { only = "Shaman",
        { "text", text = "The Shrine of Eternal Flame" },
        { "text", text = "Climb on past |cOXP_FRIENDLY_Braldir Ashmantle|r to the peak. Drink the |cOXP_LOOT_Fire Sapta|r beside the rock statue there to see the |cOXP_ENEMY_Minor Manifestation of Fire|r (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with Rockbiter Weapon and Earth Shock. Its |cOXP_LOOT_Glowing Ember|r drops every time." },
        { "goto", x = 31.9, y = 64.5, zone = "1432" },
        { "complete", obj = 1, quest = 94467, text = "Use |cOXP_LOOT_Fire Sapta|r (|cOXP_LOOT_Fire Sapta|r, beside the statue)" },
        { "goto", x = 31.96, y = 64.42, zone = "1432" },
        { "complete", obj = 1, quest = 94467, text = "Glowing Ember: 1 (|cOXP_LOOT_Glowing Ember|r: |cOXP_ENEMY_Minor Manifestation of Fire|r)" },
        { "mob", name = "Minor Manifestation of Fire" },
      },
      { only = "Shaman",
        { "text", text = "The |cOXP_PICK_Brazier of the Dormant Flame|r" },
        { "text", text = "Click the |cOXP_PICK_Brazier of the Dormant Flame|r atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit |cOXP_LOOT_Torch of Eternal Flame|r." },
        { "goto", x = 31.79, y = 64.52, zone = "1432" },
        { "turnin", quest = 94467, text = "Turn in Call of Fire" },
        { "goto", x = 31.79, y = 64.52, zone = "1432" },
        { "accept", quest = 94468, text = "Accept Call of Fire" },
      },
      { only = "Human Warlock",
        { "text", text = "Class quest: Voidwalker (Alliance)" },
        { "text", text = "Gakin's Summons (Humans)" },
        { "text", text = "At 10 |cOXP_FRIENDLY_Remen Marcot|r, in the cellar of the Lion's Pride Inn in Goldshire (the stairs down are in the back room past the butcher's table), sends you to |cOXP_FRIENDLY_Gakin the Darkbinder|r in Stormwind." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 44.49, y = 66.27, zone = "1429" },
        { "accept", quest = 1685, text = "Accept Gakin's Summons (|cOXP_FRIENDLY_Remen Marcot|r, Lion's Pride Inn cellar)" },
        { "target", name = "Remen Marcot" },
      },
      { only = "Gnome Warlock",
        { "text", text = "The Slaughtered Lamb (Gnomes)" },
        { "text", text = "At 10 |cOXP_FRIENDLY_Lago Blackwrench|r, the warlock trainer in Ironforge's |cOXP_PICK_Forlorn Cavern|r, sends you to |cOXP_FRIENDLY_Gakin the Darkbinder|r in Stormwind. Take the Deeprun Tram from |cOXP_PICK_Tinker Town|r. If |cOXP_FRIENDLY_Lago Blackwrench|r does not offer it, go to |cOXP_FRIENDLY_Gakin the Darkbinder|r anyway: he still gives you the next quest." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 47.63, y = 9.26, zone = "1455" },
        { "accept", quest = 1715, text = "Accept The Slaughtered Lamb (|cOXP_FRIENDLY_Lago Blackwrench|r, |cOXP_PICK_Forlorn Cavern|r)" },
        { "target", name = "Lago Blackwrench" },
      },
      { only = "Warlock",
        { "text", text = "|cOXP_FRIENDLY_Gakin the Darkbinder|r" },
        { "text", text = "The Slaughtered Lamb is the tavern in the |cOXP_PICK_Mage Quarter|r; |cOXP_FRIENDLY_Gakin the Darkbinder|r is in its cellar, down the stairs inside." },
        { "goto", only = "Human", x = 39.22, y = 85.23, zone = "1453" },
        { "turnin", only = "Human", quest = 1685, text = "Turn in Gakin's Summons" },
        { "target", name = "Gakin the Darkbinder", only = "Human" },
        { "goto", only = "Gnome", x = 39.22, y = 85.23, zone = "1453" },
        { "turnin", only = "Gnome", quest = 1715, text = "Turn in The Slaughtered Lamb" },
        { "target", name = "Gakin the Darkbinder", only = "Gnome" },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "accept", quest = 1688, text = "Accept Surena Caledon" },
        { "target", name = "Gakin the Darkbinder" },
      },
      { only = "Warlock",
        { "text", text = "|cOXP_ENEMY_Surena Caledon|r" },
        { "text", text = "|cOXP_ENEMY_Surena Caledon|r (level 9) is inside the farmhouse at the Brackwell Pumpkin Patch, south-east Elwynn near the Redridge road. |cOXP_ENEMY_Morgan the Collector|r (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on |cOXP_ENEMY_Surena Caledon|r first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop." },
        { "goto", x = 71.01, y = 80.77, zone = "1429" },
        { "mob", name = "Surena Caledon" },
        { "text", text = "Kill |cOXP_ENEMY_Surena Caledon|r" },
        { "goto", x = 71.01, y = 80.77, zone = "1429" },
        { "complete", obj = 1, quest = 1688, text = "Surena's Choker: 1" },
        { "mob", name = "Surena Caledon" },
      },
      { only = "Skyborne Warrior",
        { "text", text = "Class quest: {spell:71} and a Weapon (Alliance)" },
        { "text", text = "|cOXP_FRIENDLY_Seena Skybreaker|r in Valanaar" },
        { "text", text = "At 10, |cOXP_FRIENDLY_Seena Skybreaker|r stands with the trainers by Valanaar's west gate. A cultist, |cOXP_ENEMY_Zaal Stormshield|r, holds her family's shield at the Shrine of Akir." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 59.89, y = 72.87, zone = "2521" },
        { "accept", quest = 94003, text = "Accept The Skybreaker Bulwark" },
        { "target", name = "Seena Skybreaker" },
      },
      { only = "Skyborne Warrior",
        { "text", text = "|cOXP_ENEMY_Zaal Stormshield|r" },
        { "text", text = "Head north-west from Valanaar to the Shrine of Akir. |cOXP_ENEMY_Zaal Stormshield|r stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the |cOXP_LOOT_Skybreaker Bulwark|r." },
        { "goto", x = 56.66, y = 50.4, zone = "2521" },
        { "mob", name = "Zaal Stormshield" },
        { "text", text = "Kill |cOXP_ENEMY_Zaal Stormshield|r" },
        { "goto", x = 56.66, y = 50.4, zone = "2521" },
        { "complete", obj = 1, quest = 94003, text = "Skybreaker Bulwark: 1 (|cOXP_LOOT_Skybreaker Bulwark|r, from |cOXP_ENEMY_Zaal Stormshield|r)" },
        { "mob", name = "Zaal Stormshield" },
      },
      { only = "Skyborne Warrior",
        { "text", text = "The Skybreaker Bulwark" },
        { "text", text = "Back to |cOXP_FRIENDLY_Seena Skybreaker|r in Valanaar. She teaches Defensive Stance and gives you the |cOXP_LOOT_Stormforged Protector|r, a shield to use it with. |cOXP_ENEMY_Bartleby|r's road below still gives a weapon, once you reach Stormwind." },
        { "goto", x = 59.89, y = 72.87, zone = "2521" },
        { "turnin", quest = 94003, text = "Turn in The Skybreaker Bulwark (|cOXP_FRIENDLY_Seena Skybreaker|r: Defensive Stance)" },
        { "target", name = "Seena Skybreaker" },
      },
      { only = "Dwarf Warrior/Gnome Warrior",
        { "text", text = "Muren Stormpike" },
        { "text", text = "At 10, |cOXP_FRIENDLY_Granis Swiftaxe|r, the warrior trainer in Kharanos, sends you to Muren Stormpike in Ironforge. Any Alliance warrior may take one of the three roads, never two: in Stormwind at 10 anyway? |cOXP_FRIENDLY_Ilsa Corbin|r's A Warrior's Training is the quickest stance (one fight in a tavern), with a Haggard's weapon after it." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 47.36, y = 52.65, zone = "1426" },
        { "accept", quest = 1679, text = "Accept Muren Stormpike" },
        { "target", name = "Granis Swiftaxe" },
      },
      { only = "Dwarf Warrior/Gnome Warrior",
        { "text", text = "Muren Stormpike in Ironforge" },
        { "text", text = "Muren Stormpike stands in the |cOXP_PICK_Hall of Arms|r in the |cOXP_PICK_Military Ward|r." },
        { "goto", x = 70.77, y = 90.27, zone = "1455" },
        { "turnin", quest = 1679, text = "Turn in Muren Stormpike" },
        { "target", name = "Muren Stormpike" },
