        { "accept", quest = 6002, text = "Accept Body and Heart" },
        { "target", name = "Turak Runetotem" },
      },
      { only = "Tauren Druid",
        { "text", text = "The |cOXP_PICK_Moonkin Stone|r" },
        { "text", text = "The |cOXP_PICK_Moonkin Stone|r stands in the Barrens just south-west of Camp Taurajo, by the road out of Mulgore. Level 20 Thunderheads roam close by: clear the way first. Use the |cOXP_LOOT_Cenarion Lunardust|r by the stone: Lunaclaw (level 12-13) appears for three minutes. Kill her, then speak to the |cOXP_FRIENDLY_Lunaclaw Spirit|r that appears and ask for the strength of her body and heart: the talk is the credit. Die in the fight? Lunaclaw stays by the stone: run back and finish her." },
        { "goto", x = 42, y = 60.9, zone = "1413" },
        { "item", item = 15710, text = "Use Cenarion Lunardust" },
        { "finish", quest = 6002, text = "Finish Body and Heart: Lunaclaw Spirit" },
      },
      { only = "Tauren Druid",
        { "text", text = "Body and Heart" },
        { "text", text = "Back to |cOXP_FRIENDLY_Turak Runetotem|r on Elder Rise." },
        { "goto", x = 76.48, y = 27.22, zone = "1456" },
        { "turnin", quest = 6002, text = "Turn in Body and Heart (|cOXP_FRIENDLY_Turak Runetotem|r: Bear Form)" },
        { "target", name = "Turak Runetotem" },
      },
      { only = "Skyborne Druid",
        { "text", text = "Skyboat from Dalaran" },
        { "text", text = "Bear Form is taught on Zephras Isle. Skip this if you are still on the isle; otherwise take the skyboat from the north side of Dalaran." },
