      },
      { only = "Skyborne Druid",
        { "text", text = "Skyboat from Thunder Bluff" },
        { "text", text = "Bear Form is taught on Zephras Isle. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of Skywatcher Plateau, north of Thunder Bluff." },
        { "reach", text = "Skyboat to Zephras Isle", x = 34.3, y = 25.8, zone = "1412" },
      },
      { only = "Skyborne Druid",
        { "text", text = "|cOXP_FRIENDLY_Lotheluum Starbreeze|r" },
        { "text", text = "|cOXP_FRIENDLY_Lotheluum Starbreeze|r stands in Valanaar." },
        { "xp", level = 10, text = "Reach level 10" },
