        { "train", only = "Shaman", text = "Train at |cOXP_FRIENDLY_Eldrun Stormbreaker|r" },
        { "target", name = "Eldrun Stormbreaker", only = "Shaman" },
      },
      { only = "NightElf Rogue",
        { "text", text = "|cOXP_FRIENDLY_Syurna|r" },
        { "text", text = "Head west to Darnassus. |cOXP_FRIENDLY_Syurna|r is below ground in the Cenarion Enclave: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground." },
        { "goto", x = 36.99, y = 21.91, zone = "1457" },
        { "turnin", quest = 2241, text = "Turn in The Apple Falls" },
        { "target", name = "Syurna" },
        { "goto", x = 36.99, y = 21.91, zone = "1457" },
        { "accept", quest = 2242, text = "Accept Destiny Calls" },
        { "target", name = "Syurna" },
      },
      { only = "NightElf Rogue",
        { "text", text = "|cOXP_ENEMY_Sethir the Ancient|r" },
        { "text", text = "|cOXP_ENEMY_Sethir the Ancient|r (level 12 satyr) lives out on a great branch north of the Oracle Glade: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then Sprint away. He is back 8 1/2 minutes after a death." },
        { "goto", x = 37.11, y = 22.83, zone = "1438" },
        { "complete", obj = 1, quest = 2242, text = "Sethir's Journal: 1" },
        { "mob", name = "Sethir the Ancient" },
      },
      { only = "NightElf Rogue",
        { "text", text = "Back to |cOXP_FRIENDLY_Syurna|r" },
        { "goto", x = 36.99, y = 21.91, zone = "1457" },
        { "turnin", quest = 2242, text = "Turn in Destiny Calls (|cOXP_FRIENDLY_Syurna|r, Darnassus)" },
        { "target", name = "Syurna" },
      },
      { only = "Priest", when = { { "onquest", neg = true, quests = { 5672, 5673, 5674, 5675 } } },
        { "text", text = "Elune's Grace: |cOXP_FRIENDLY_Priestess Alathea|r" },
        { "text", text = "At 20, |cOXP_FRIENDLY_Priestess Alathea|r on the upper balcony of the Temple of the Moon, beside |cOXP_FRIENDLY_Tyrande Whisperwind|r, teaches Elune's Grace with a quest she gives and takes back at once. In Forever, Elune's Grace halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "accept", quest = 5672, text = "Accept Elune's Grace" },
        { "target", name = "Priestess Alathea" },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
