      { only = "NightElf Druid/Skyborne Druid",
        { "text", text = "|cOXP_FRIENDLY_Dendrite Starblaze|r" },
        { "text", text = "Cast Teleport: Moonglade: |cOXP_FRIENDLY_Dendrite Starblaze|r stands upstairs in the building beside you. He hands you the |cOXP_LOOT_Empty Cliffspring Falls Sampler|r. Then fly to Auberdine (learn the Moonglade flight path at Sindrayl first if you have not)." },
        { "goto", x = 56.21, y = 30.64, zone = "1450" },
        { "turnin", quest = 6121, text = "Turn in Lessons Anew" },
