      { only = "Tauren Druid/Skyborne Druid",
        { "text", text = "Lessons Anew" },
        { "text", text = "|cOXP_FRIENDLY_Turak Runetotem|r stands in the druids' hut on Elder Rise; |cOXP_FRIENDLY_Hana Lighthoof|r, the Skyborne druid trainer where the airship from Zephras Isle lands in northern Mulgore, gives the same quest. No Herbalism? |cOXP_FRIENDLY_Hula'mahi|r at the Crossroads sells |cOXP_LOOT_Earthroot|r later, or buy five on the Auction House now." },
        { "xp", level = 14, text = "Reach level 14" },
        { "goto", x = 76.48, y = 27.22, zone = "1456" },
        { "accept", quest = 6126, text = "Accept Lessons Anew (|cOXP_FRIENDLY_Turak Runetotem|r, or |cOXP_FRIENDLY_Hana Lighthoof|r in northern Mulgore)" },
        { "target", name = "Turak Runetotem" },
      },
      { only = "Tauren Druid/Skyborne Druid",
        { "text", text = "|cOXP_FRIENDLY_Dendrite Starblaze|r" },
        { "text", text = "Cast Teleport: Moonglade: |cOXP_FRIENDLY_Dendrite Starblaze|r stands upstairs in the building beside you. He hands you the |cOXP_LOOT_Empty Dreadmist Peak Sampler|r. |cOXP_FRIENDLY_Bunthen Plainswind|r flies druids to Thunder Bluff; fly on to the Crossroads from there." },
        { "goto", x = 56.21, y = 30.64, zone = "1450" },
        { "turnin", quest = 6126, text = "Turn in Lessons Anew" },
