        { "accept", quest = 272, text = "Accept Trial of the Sea Lion" },
        { "target", name = "Tajarri" },
      },
      { only = "NightElf Druid/Skyborne Druid",
        { "text", text = "|cOXP_LOOT_Half Pendant of Aquatic Agility|r" },
        { "text", text = "Fly from Nighthaven to Auberdine. The |cOXP_PICK_Strange Lockbox|r lies far out on the sea floor off the north coast, between tall rocks west of where the Cliffspring River reaches the sea: it cannot be seen from the east side of the rocks. Watch your breath and the Darkshore Threshers; fight above water." },
        { "fly", inst = 1, name = "Auberdine", text = "Fly to Auberdine", wx = 557.7, wy = 6341.4 },
        { "goto", x = 48.87, y = 11.32, zone = "1439" },
        { "collect", count = 1, item = 15883, text = "Half Pendant of Aquatic Agility: 1 (|cOXP_LOOT_Half Pendant of Aquatic Agility|r, from the |cOXP_PICK_Strange Lockbox|r)" },
      },
      { only = "NightElf Druid/Skyborne Druid",
        { "text", text = "|cOXP_LOOT_Half Pendant of Aquatic Endurance|r" },
        { "text", text = "Take the boat from Auberdine to Stormwind and fly to Sentinel Hill. Head west to the coast: the |cOXP_PICK_Strange Lockbox|r lies far out on the sea floor beside a bubbling fissure (air), west of a sunken anchor. Sharks roam here; do not swim on past the wreck beyond it, the deep water brings fatigue." },
        { "fly", inst = 0, name = "Sentinel Hill", text = "Fly to Sentinel Hill", wx = 1036.7, wy = -10628.9 },
        { "goto", x = 17.94, y = 33.18, zone = "1436" },
        { "collect", count = 1, item = 15882, text = "Half Pendant of Aquatic Endurance: 1 (|cOXP_LOOT_Half Pendant of Aquatic Endurance|r, from the |cOXP_PICK_Strange Lockbox|r)" },
      },
      { only = "NightElf Druid/Skyborne Druid",
        { "text", text = "|cOXP_LOOT_Pendant of the Sea Lion|r" },
        { "text", text = "Cast Teleport: Moonglade. With both halves in your bags, stand by the Shrine of Remulos on the north-west shore and use the |cOXP_LOOT_Half Pendant of Aquatic Agility|r to join them, then cast Teleport: Moonglade again (it works inside Moonglade) to land by |cOXP_FRIENDLY_Dendrite Starblaze|r. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Afterwards |cOXP_FRIENDLY_Silva Fil'naveth|r, in the middle of Nighthaven, flies druids straight to Rut'theran Village." },
        { "goto", x = 36, y = 41.42, zone = "1450" },
        { "complete", obj = 1, quest = 272, text = "Pendant of the Sea Lion: 1 (|cOXP_LOOT_Pendant of the Sea Lion|r: join the halves at the shrine)" },
